function TeachBack({instructions,data,language,mutate,pending}:{instructions:Instruction[];data:WorkspaceData;language:string;mutate:Mutation;pending:boolean}) { const ui=useUi();
  const [selected,setSelected]=useState(instructions.find(i=>i.kind==="MEDICATION")?.id || instructions[0]?.id || "");const [answer,setAnswer]=useState("");const [inputMode,setInputMode]=useState<"TEXT"|"VOICE">("TEXT");const [confirmed,setConfirmed]=useState(false);const [assisted,setAssisted]=useState(false);const [result,setResult]=useState<Attempt|null>(null);const {recording,status:voiceStatus,start:record,stop:stopRecording,cancel:cancelRecording,setStatus:setVoiceStatus}=useVoiceInput(language,selected,text=>{setAnswer(text);setInputMode("VOICE");setConfirmed(false);});
  useEffect(()=>{const query=new URLSearchParams(window.location.search).get("instructionId");if(query && instructions.some(i=>i.id===query))setSelected(query);},[instructions]);
  const i=instructions.find(x=>x.id===selected);const approved=i?approvedText(i,language):{text:"",language:"en",fallback:false};const explanation=approved.text;
  async function submit(e:React.FormEvent){e.preventDefault();try{const attempt=await mutate("teachback",{instructionId:selected,transcript:answer,inputMode,transcriptConfirmed:inputMode==="TEXT" || confirmed,personType:data.user.role==="FAMILY"?"CAREGIVER":assisted?"ASSISTED_PATIENT":"PATIENT"});setResult(attempt as Attempt);}catch{}}
  if(!i)return <div className="empty panel"><AudioLines/><h2><UiText>{"No instruction available for teach-back"}</UiText></h2><p><UiText>{"Teach-back begins after your care team publishes approved instructions."}</UiText></p></div>;
  return <><div className="two-column teachback-columns"><section className="panel teachback-form"><div className="panel-heading"><h2><UiText>{"In your own words."}</UiText></h2><span className="icon-tile"><AudioLines size={20}/></span></div><label><UiText>{"Choose one instruction"}</UiText><select value={selected} onChange={e=>{setSelected(e.target.value);setResult(null);setAnswer("");setConfirmed(false);}}>{instructions.map(x=><option key={x.id} value={x.id}>{x.title}</option>)}</select></label><div className="approved-passage"><span className="micro-label"><ShieldCheck size={14}/><UiText>{" YOUR APPROVED INSTRUCTION"}</UiText></span><p lang={approved.language}><UiText>{explanation}</UiText></p>{approved.fallback && <p className="translation-notice" role="status"><UiText>{"A clinician-approved "}</UiText>{languageInfo(language).name}<UiText>{" translation is not available yet. Showing approved "}</UiText>{languageInfo(approved.language).name}<UiText>{" text."}</UiText></p>}<button className="text-link" onClick={async()=>{if(await speak(explanation,approved.language)===false)setVoiceStatus("Your browser does not have a voice for this approved text’s language. Read the text instead.");}}><Volume2 size={16}/><UiText>{"Listen again"}</UiText></button></div><form onSubmit={submit}><label htmlFor="teachback-answer"><UiText>{i.kind==="MEDICATION"?"In your own words, tell us how you will take this medicine.":"In your own words, tell us what this instruction asks you to do."}</UiText></label><textarea id="teachback-answer" lang={languageInfo(language).locale} readOnly={recording} rows={5} placeholder={ui("Tell us what you understood…")} value={answer} onChange={e=>{setAnswer(e.target.value);setConfirmed(false);}} required minLength={2} maxLength={3000}/><div className="voice-input-language"><Languages size={16}/><UiText>{"Voice input language: "}</UiText><span>{languageInfo(language).native}</span></div><div className="voice-toolbar"><button className="button secondary" type="button" onClick={()=>recording?stopRecording():record(answer)}>{recording?<Square size={16}/>:<Mic size={16}/>} <UiText>{recording?"Stop recording":"Use my voice"}</UiText></button>{inputMode==="VOICE" && <button type="button" className="text-link" onClick={()=>{cancelRecording();setInputMode("TEXT");setConfirmed(false);}}><UiText>{"Use text instead"}</UiText></button>}</div><small className="muted"><UiText>{"Voice transcription uses your browser’s speech service when available. CareBodha does not store audio. Text is always available."}</UiText></small>{voiceStatus && <div className="alert violet" role="status"><UiText>{voiceStatus}</UiText></div>}{inputMode==="VOICE" && <label className="checkbox-row"><input type="checkbox" checked={confirmed} disabled={recording} onChange={e=>setConfirmed(e.target.checked)}/><UiText>{"I reviewed this transcript. These are my words."}</UiText></label>}{data.user.role!=="FAMILY" && <label className="checkbox-row"><input type="checkbox" checked={assisted} onChange={e=>setAssisted(e.target.checked)}/><UiText>{"A caregiver helped me explain this instruction."}</UiText></label>}{data.user.role==="FAMILY" && <div className="alert violet"><UiText>{"Recorded as caregiver teach-back. This does not confirm the patient’s understanding."}</UiText></div>}<button className="button primary full" disabled={pending || recording || (inputMode==="VOICE" && !confirmed)}><UiText>{pending?"Checking…":"Check my understanding"}</UiText></button></form></section><div className="stack">{result?<section className="panel result-panel" aria-live="polite"><span className="micro-label"><UiText>{result.method.toUpperCase()}</UiText><UiText>{" COMPARISON"}</UiText></span><h2><UiText>{result.status==="MATCH"?"The checked details agree.":"Let’s look at the details together."}</UiText></h2><Status status={result.status}/>{result.findings.map(f=><div className={`finding ${f.status==="MISMATCH"?"finding-mismatch":""}`} key={f.id}><div><strong><UiText>{f.fieldName}</UiText></strong><Status status={f.status}/></div><p>{f.explanation}</p><dl><dt><UiText>{"Approved"}</UiText></dt><dd>{f.approvedValue}</dd><dt><UiText>{"Your words"}</UiText></dt><dd>{f.statedValue}</dd></dl>{f.supportingQuote && <blockquote>“{f.supportingQuote}”</blockquote>}</div>)}<p className="muted"><UiText>{"A match confirms agreement with this instruction. It does not confirm clinical safety or adherence."}</UiText></p><div className="card-buttons"><button className="button primary" onClick={()=>{setResult(null);setAnswer("");setConfirmed(false);}}><UiText>{"Try again"}</UiText></button><Link className="button secondary" href={`/app/questions?instructionId=${selected}`}><UiText>{"Ask the care team"}</UiText></Link></div></section>:<section className="panel supportive-panel"><span className="icon-tile large-icon"><Heart size={30}/></span><h2><UiText>{"This is a conversation,"}</UiText><br/><UiText>{"not a test."}</UiText></h2><p><UiText>{"Take your time. We’ll compare your answer with your approved instruction and show the details that may need another look."}</UiText></p><div className="workflow-step"><span><Check size={16}/></span><p><UiText>{"One instruction at a time"}</UiText></p></div><div className="workflow-step"><span><Check size={16}/></span><p><UiText>{"Specific, supportive explanations"}</UiText></p></div><div className="workflow-step"><span><Check size={16}/></span><p><UiText>{"Your care team handles missing information"}</UiText></p></div>{data.mode==="demo" && i.kind==="MEDICATION" && <div className="demo-fixtures"><span className="micro-label"><UiText>{"FICTIONAL DEMO EXAMPLES"}</UiText></span><button className="text-link" onClick={()=>{setInputMode("TEXT");setAnswer("I will take one tablet once daily after food.");}}><UiText>{"Try a frequency mismatch"}</UiText></button><button className="text-link" onClick={()=>{setInputMode("TEXT");setAnswer(`I will take one tablet ${i.frequency || "twice daily"} after food.`);}}><UiText>{"Try an agreeing answer"}</UiText></button><small><UiText>{"The selected medicine is shown above. We check dose, unit, frequency, and timing; a stated medicine name is checked separately."}</UiText></small></div>}</section>}</div></div><AttemptHistory attempts={data.attempts.filter(a=>a.answeredById===data.user.id)} timezone={data.patients.find(p=>p.id===data.selectedPatientId)?.timezone || "Asia/Kolkata"}/></>;
}
