function DocumentUpload({data,patient,mutate,pending}:{data:WorkspaceData;patient:Patient;mutate:Mutation;pending:boolean}) { const ui=useUi();
  const [text,setText]=useState("");const [file,setFile]=useState<File|null>(null);const [uploaded,setUploaded]=useState(false);const [uploading,setUploading]=useState(false);const [uploadError,setUploadError]=useState("");
  async function submit(e:React.FormEvent){e.preventDefault();setUploading(true);setUploaded(false);setUploadError("");try{if(file && !text.trim() && data.storageDriver==="vercel-blob"){const permit=await mutate("documents/upload-authorization",{patientId:patient.id,name:file.name,mimeType:file.type,size:file.size}) as {pathname:string;proof:string};const {upload}=await import("@vercel/blob/client");await upload(permit.pathname,file,{access:"private",contentType:file.type,handleUploadUrl:"/api/blob/upload-token",clientPayload:permit.proof});await mutate("documents/blob",{proof:permit.proof});}else{const form=new FormData();form.set("patientId",patient.id);if(text.trim())form.set("text",text);else if(file)form.set("file",file);await mutate("documents",form);}setUploaded(true);setText("");setFile(null);}catch(error){setUploadError(error instanceof Error?error.message:"Unable to upload. Choose the file again.");}finally{setUploading(false);}}
  return <><div className="two-column"><section className="panel"><div className="panel-heading"><h2><UiText>{"Add a source document"}</UiText></h2><Upload size={22}/></div><p><UiText>{"For "}</UiText>{patient.user.name}<UiText>{". Files stay private and require authorized access."}</UiText></p><form onSubmit={submit}><label className="file-drop"><Upload size={28}/><strong><UiText>{"Choose a PDF, PNG, or JPEG"}</UiText></strong><span><UiText>{"Text PDFs · Images with configured OCR · Up to 10 MB"}</UiText></span><input type="file" accept="application/pdf,image/png,image/jpeg" aria-label={ui("Source document file")} onChange={e=>{setFile(e.target.files?.[0] || null);setText("");}}/>{file && <small>{file.name}</small>}</label><span className="form-divider"><UiText>{"OR PASTE DISCHARGE TEXT"}</UiText></span><label><UiText>{"Original discharge text"}</UiText><textarea rows={6} value={text} maxLength={100000} onChange={e=>{setText(e.target.value);if(e.target.value)setFile(null);}} placeholder={ui("Paste the doctor’s existing instructions exactly as written.")}/></label><button className="button primary full" disabled={pending || uploading || (!file && !text.trim())}><UiText>{uploading?"Uploading privately…":"Queue document processing"}</UiText></button>{uploadError && <p className="red" role="alert"><UiText>{uploadError}</UiText></p>}{uploaded && <p className="green" role="status"><UiText>{"Document queued. Processing status appears below."}</UiText></p>}</form></section><section className="panel supportive-panel"><FileText size={40} className="violet"/><h2><UiText>{"Source first."}</UiText><br/><UiText>{"Approval always."}</UiText></h2>{data.providerMode==="manual" && <div className="alert violet"><UiText>{"Source fields are extracted automatically when explicitly stated. Review every draft; missing details stay empty and unclear text needs doctor clarification."}</UiText></div>}<p><UiText>{"Extraction creates a draft. Patients cannot read it until you review the details, review the explanations in both languages, and approve the plan."}</UiText></p><div className="alert amber"><UiText>{"If OCR is unavailable, image processing reports failure and offers manual entry. No processed result is fabricated."}</UiText></div>{data.mode==="demo" && <><span className="micro-label"><UiText>{"DEMO PROCESSING"}</UiText></span><p><UiText>{"The three provided fictional documents are supported by deterministic extraction. Other documents report the demo limitation; configure live AI for freeform extraction."}</UiText></p><a className="text-link" href="/demo-source"><UiText>{"Copy fictional source text"}</UiText></a></>}</section></div><section className="panel"><div className="panel-heading"><h2><UiText>{"Document processing"}</UiText></h2><Link className="text-link" href="/app/review"><UiText>{"Open plan review"}</UiText></Link></div>{data.documents.map(d=><div className="document-row" key={d.id}><span className="icon-tile"><FileText size={20}/></span><div><strong>{d.name}</strong><p><UiText>{formatDate(d.createdAt)}</UiText> · <UiText>{d.mimeType}</UiText></p>{d.errorCode && <div className="red"><UiText>{d.errorCode.replaceAll("_"," ").toLowerCase()}</UiText><UiText>{". Paste the source text manually or configure the required provider."}</UiText></div>}{d.jobs.map(j=><small key={j.id}><UiText>{"Job: "}</UiText><UiText>{statusNames[j.status] || j.status}</UiText><UiText>{" · attempts "}</UiText><UiText>{j.attempts}</UiText>/3</small>)}</div><Status status={d.status}/><a className="button secondary" href={`/api/v1/documents/${d.id}`}><UiText>{"Download source"}</UiText></a></div>)}</section></>;
}
function ExtractionReview({data,mutate,pending}:{data:WorkspaceData;mutate:Mutation;pending:boolean}) {
  const [versionId,setVersionId]=useState("");const versions=data.plans.flatMap(p=>p.versions.map(v=>({...v,planTitle:p.title,planId:p.id})));const version=versions.find(v=>v.id===versionId) || versions.find(v=>v.status==="DRAFT") || versions[0];
  const [approved,setApproved]=useState(false);
  const recoveryAttempts=useRef(new Set<string>());
  useEffect(()=>{
    if(!version||!isUntouchedLegacyExtraction(version)||recoveryAttempts.current.has(version.id))return;
    recoveryAttempts.current.add(version.id);
    void mutate(`versions/${version.id}/extract`).catch(()=>{});
  },[version,mutate]);
  if(!version)return <div className="empty panel"><FileText/><h2><UiText>{"No draft to review"}</UiText></h2><p><UiText>{"Upload or paste a source document to start extraction."}</UiText></p><Link href="/app/upload" className="button primary"><UiText>{"Add document"}</UiText></Link></div>;
  const draft=version.status==="DRAFT";
  return <><div className="section-toolbar"><label className="version-picker"><UiText>{"Plan version"}</UiText><select value={version.id} onChange={e=>{setVersionId(e.target.value);setApproved(false);}}>{versions.map(v=><option key={v.id} value={v.id}><UiText>{v.planTitle}</UiText><UiText>{" · v"}</UiText><UiText>{v.number}</UiText> · <UiText>{v.status.toLowerCase()}</UiText></option>)}</select></label><Status status={version.status}/><span className="badge"><UiText>{version.method.toUpperCase()}</UiText><UiText>{" EXTRACTION"}</UiText></span>{!draft && <button className="button secondary" disabled={pending} onClick={()=>void mutate(`plans/${version.planId}/versions`).then(()=>setVersionId("")).catch(()=>{})}><Plus size={16}/><UiText>{"Create new draft version"}</UiText></button>}</div>{approved && <div className="alert green" role="status"><UiText>{"Approved and published. The patient now receives this version."}</UiText></div>}<div className="review-source panel"><div className="panel-heading"><h2><UiText>{"Original source"}</UiText></h2><ShieldCheck size={19}/></div><pre>{version.document?.sourceText || <UiText>{"Source text is available from the authorized document download."}</UiText>}</pre>{version.document && <a className="text-link" href={`/api/v1/documents/${version.document.id}`}><UiText>{"Download original document"}</UiText></a>}<p className="muted"><UiText>{"Uploaded text is untrusted data. Missing values stay empty; unclear or contradictory sources require doctor clarification."}</UiText></p></div>{draft && ["clinician entry","source field extraction v1","source field extraction v2"].includes(version.method) && <section className="panel"><p><UiText>{"Extract the original source into a fresh draft. Existing edits are kept in the previous version; the new draft requires review."}</UiText></p><button className="button secondary" disabled={pending} onClick={()=>void mutate(`versions/${version.id}/extract-new`).then(result=>setVersionId((result as {id:string}).id)).catch(()=>{})}><RefreshCw size={17}/><UiText>{"Extract source into a new draft"}</UiText></button></section>}{version.instructions.map(i=><InstructionEditor key={`${i.id}-${i.reviewState}`} instruction={i} draft={draft} mutate={mutate} pending={pending}/>)}{draft && <ReviewActions key={version.id} versionId={version.id} instructions={version.instructions} pending={pending} mutate={mutate} onApproved={()=>setApproved(true)}/> }</>;
}
function InstructionEditor({instruction:i,draft,mutate,pending}:{instruction:Instruction;draft:boolean;mutate:Mutation;pending:boolean}) { const ui=useUi();
  const [kind,setKind]=useState(i.kind);const [instructionTitle,setInstructionTitle]=useState(i.title);
  const [values,setValues]=useState(Object.fromEntries(clinicalFields.map(f=>[f,i[f] || ""])) as Record<typeof clinicalFields[number],string>);const [source,setSource]=useState(i.sourcePassage);const [unclear,setUnclear]=useState(i.sourceUnclear);const [followUpAt,setFollowUpAt]=useState(i.followUpAt || "");
  async function save(){const instruction={kind,title:instructionTitle,...Object.fromEntries(clinicalFields.map(f=>[f,values[f] || null])),followUpAt:followUpAt || null,sourcePassage:source,sourceLocation:i.sourceLocation,sourceUnclear:unclear};try{await mutate(`instructions/${i.id}`,{instruction,reviewed:true},"PATCH");}catch{}}
  return <article id={`review-instruction-${i.id}`} className="panel extraction-card"><div className="panel-heading"><div><span className="micro-label"><UiText>{i.kind}</UiText> · {i.sourceLocation}</span><h2>{i.title}</h2></div><Status status={i.reviewState}/></div><div className="extraction-layout"><div><h3><UiText>{"Structured source fields"}</UiText></h3><label><UiText>{"Instruction title"}</UiText><input value={instructionTitle} maxLength={200} disabled={!draft || pending} onChange={e=>setInstructionTitle(e.target.value)}/></label><label><UiText>{"Instruction type"}</UiText><select value={kind} disabled={!draft || pending} onChange={e=>setKind(e.target.value as Instruction["kind"])}>{["MEDICATION","FOLLOW_UP","CARE","WARNING","CONTACT"].map(k=><option key={k}><UiText>{k}</UiText></option>)}</select></label><div className="field-grid">{kind==="MEDICATION" && clinicalFields.map(f=><label key={f}><UiText>{f==="medicationName"?"Medication name":f}</UiText><input value={values[f]} placeholder="Not included in source" disabled={!draft || pending} onChange={e=>setValues({...values,[f]:e.target.value})}/></label>)}{kind==="FOLLOW_UP" && <label><UiText>{"Explicit follow-up timestamp (ISO8601)"}</UiText><input value={followUpAt} disabled={!draft || pending} onChange={e=>setFollowUpAt(e.target.value)} placeholder={ui("Leave empty if not explicit")}/></label>}</div><label><UiText>{"Exact source passage"}</UiText><textarea value={source} disabled={!draft || pending} rows={3} onChange={e=>setSource(e.target.value)}/></label>{draft && <><label className="checkbox-row"><input type="checkbox" checked={unclear} onChange={e=>setUnclear(e.target.checked)}/><UiText>{"Source is unclear or contradictory — doctor clarification required"}</UiText></label><button className="button secondary" disabled={pending || !instructionTitle.trim()} onClick={()=>void save()}><Check size={17}/><UiText>{"Confirm extraction review"}</UiText></button></>}</div><div className="explanation-review"><h3><UiText>{"Explanation & translation review"}</UiText></h3><p className="muted"><UiText>{"Confirm that names, doses, units, routes, frequency, timing, and duration preserve the source meaning."}</UiText></p>{i.explanations.map(e=><ExplanationEditor key={`${e.id}-${e.status}-${e.text}`} explanation={e} draft={draft} mutate={mutate} pending={pending}/>)}{!i.explanations.length && <div className="empty-inline"><UiText>{"Confirm extraction review, then generate draft explanations below."}</UiText></div>}</div></div></article>;
}
function ExplanationEditor({explanation:e,draft,mutate,pending}:{explanation:Json<InstructionExplanation>;draft:boolean;mutate:Mutation;pending:boolean}) { const ui=useUi();
  const [text,setText]=useState(e.text);
  return <div className="explanation-block"><div className="panel-heading"><strong>{`${languageInfo(e.language).native} — ${languageInfo(e.language).name}`}</strong><Status status={e.status}/></div><textarea aria-label={ui(`${languageInfo(e.language).name} explanation`)} lang={e.language} placeholder={ui(`Write a clinician-reviewed ${languageInfo(e.language).name} explanation`)} value={text} disabled={!draft || pending} rows={3} onChange={event=>setText(event.target.value)}/><small><UiText>{"Source fields: "}</UiText><UiText>{e.sourceFields.join(", ") || "original passage"}</UiText> · <UiText>{e.method}</UiText></small>{draft && <button className="text-link" disabled={pending || !text.trim()} onClick={()=>void mutate(`explanations/${e.id}`,{text,reviewed:true},"PATCH").catch(()=>{})}><Check size={15}/><UiText>{"Confirm "}</UiText>{languageInfo(e.language).name}<UiText>{" review"}</UiText></button>}</div>;
}







